// The embedded mustty: xterm.js plus the wasm Session. Loaded with import() once the demo nears the
// viewport, so neither the wasm nor xterm.js is part of the first paint.
import "@xterm/xterm/css/xterm.css";
import { Terminal } from "@xterm/xterm";
import { FitAddon } from "@xterm/addon-fit";
import { Unicode11Addon } from "@xterm/addon-unicode11";
// Generated by `pnpm build:wasm` (wasm-pack --target web) from crates/mustty-web
import init, { Session } from "./pkg/mustty_web.js";
import { currentTheme, onThemeChange } from "./theme.js";

const FONT = '"JetBrains Mono", "JetBrains Mono Fallback", ui-monospace, SFMono-Regular, Menlo, monospace';

// Starts mustty in `host` (an empty element) and returns the Terminal
export async function mountTerminal(host) {
  // xterm measures its cell size once, at open: wait (briefly) for the web font so the grid uses it
  await Promise.race([
    Promise.all([document.fonts.load(`400 15px "JetBrains Mono"`), document.fonts.load(`700 15px "JetBrains Mono"`)]),
    new Promise((resolve) => setTimeout(resolve, 1500)),
  ]).catch(() => {});
  await init();

  const term = new Terminal({
    allowProposedApi: true, // the unicode11 width table
    cursorStyle: "bar",
    fontFamily: FONT,
    fontSize: 15,
    lineHeight: 1.2,
    macOptionIsMeta: true, // Option+B / Option+F move by word, as in macOS terminals
    theme: currentTheme(),
  });
  const fit = new FitAddon();
  term.loadAddon(fit);
  term.loadAddon(new Unicode11Addon());
  term.unicode.activeVersion = "11";
  term.open(host);
  fit.fit();
  // Swaps the palette in place: the buffer, and so the document and the cursor, stay as they are
  onThemeChange((theme) => {
    term.options.theme = theme;
    term.refresh(0, term.rows - 1);
  });

  const session = new Session(term.cols, term.rows, (bytes) => term.write(bytes));
  term.onData((data) => session.feed(data));
  term.onResize(({ cols, rows }) => session.resize(cols, rows));
  new ResizeObserver(() => fit.fit()).observe(host);
  const loop = () => {
    session.frame();
    requestAnimationFrame(loop);
  };
  requestAnimationFrame(loop);
  return term;
}
